using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Threading;using Musikbox;
class Features57Tests {
 static int count;static void Check(bool ok,string name){if(!ok)throw new Exception(name);count++;Console.WriteLine("PASS "+name);}static void Bad(Action a,string name){bool failed=false;try{a();}catch{failed=true;}Check(failed,name);}
 static void Main(string[] args){string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);string source=Path.GetFullPath(args[1]);var songs=new List<Song>();for(int i=0;i<4;i++){string folder=Path.Combine(root,i<2?"A":"B");Directory.CreateDirectory(folder);string file=Path.Combine(folder,"Artist "+i+" - Title "+i+".mp3");File.Copy(source,file,true);TagFields.Write(file,new Dictionary<string,string>{{"artist","Artist "+i},{"title","Title "+i},{"album","Album"},{"year","2026"}});songs.Add(MediaMetadata.Read(file));}
  foreach(string text in new[]{"Glen Campbell (Live)","Glen Campbell [Video]","Glen Campbell (Live) (Video)","Glen Campbell (Live [2026])"})Check(SearchText.Clean(text)=="Glen Campbell","Klammern "+text);
  Check(!Uri.UnescapeDataString(CoverSearch.SearchUrl("Glen Campbell (Live)","Sunflower [Video]")).Contains("Video"),"Coverabfrage bereinigt");Check(SearchText.Relevance("piaf edith","Édith Piaf")==1,"Akzente und Wortreihenfolge");
  var duet=new Song{Artist="Alison Krauss feat. Brad Paisley",Title="Whiskey Lullaby",Source=source};foreach(string query in new[]{"Krauss Paisley","Brad Paisley","pai kra","Alison Krauss"})Check(LibrarySearch.Matches(duet,"",query),"Duett "+query);
  foreach(string join in new[]{"feat.","ft.","featuring","x","&","+","and","und"})Check(SearchText.Artists("Alison Krauss "+join+" Brad Paisley").Contains("Brad Paisley"),"Künstlerverbindung "+join);
  Check(SearchText.Artists("AC/DC").Length==1&&SearchText.Artists("Earth, Wind & Fire").Length==1,"Gruppennamen erhalten");Check(CoverSearch.SearchUrls(duet.Artist,duet.Title).Length==3,"Duettpartner-Suchkombinationen");
  foreach(string artist in new[]{"Herbert Grönemeyer","Glen Campbell","Eros Ramazzotti","Laura Pausini","Édith Piaf","Mylène Farmer","Julio Iglesias","André Hazes","António Zambujo"})Check(LibrarySearch.VoiceMatches(new Song{Artist=artist,Title="Test",Source=source},artist),"Mehrsprachiger Textabgleich "+artist);
  Check(LibrarySearch.VoiceMatches(new Song{Artist="Glen Campbell",Title="Sunflower",Source=source},"Glenn Campbel"),"Phonetische Abweichung");Check(LibrarySearch.FindVoice(new[]{duet,duet.Copy()},new[]{"Whiskey Lullaby"})==null,"Mehrdeutigkeit sicher");
  foreach(int start in new[]{1,7,99})for(int flags=0;flags<8;flags++){bool total=(flags&1)!=0,zeros=(flags&2)!=0,reset=(flags&4)!=0;var plan=TrackNumbering.Plan(songs,start,total,zeros,reset);Check(plan.Count==4,"Trackplan Start="+start+" Optionen="+flags);var action=FileTagAction.Apply(plan,Path.Combine(root,"undo"));for(int i=0;i<4;i++){int n=start+(reset?i%2:i),size=reset?2:4,width=zeros?Math.Max(2,(start+size-1).ToString().Length):1;string expected=n.ToString(new string('0',width))+(total?"/"+size:"");Check(TagFields.Read(songs[i].Source)["track"]==expected,"TRCK gespeichert "+expected);}action.Restore(false);Check(TagFields.Read(songs[0].Source)["track"]=="","Track-Rücknahme");action.Restore(true);action.Restore(false);}
  Check(TrackNumbering.Plan(new[]{songs[0]},1,true,true,true)[0].Description=="01/1","Einzeltitel");
  var values=TagFields.Read(songs[0].Source);Check(TagFormat.Expand("$upper(%artist%) - $replace(%title%,'Title','Song')",values)=="ARTIST 0 - Song 0","Freies Format und Funktionen");Bad(()=>TagFormat.Expand("%missing%",values),"Fehlende Metadaten abgewiesen");Bad(()=>TagFormat.FileName("CON.mp3"),"Reservierter Name abgewiesen");
  var tagPlan=TagConversion.Plan(new[]{songs[0]},1,"%artist% - %title%","","");Check(tagPlan[0].Fields["title"]=="Title 0","Dateiname → Tag Vorschau");var tagAction=FileTagAction.Apply(tagPlan,Path.Combine(root,"undo"));tagAction.Restore(false);
  var rename=TagConversion.Plan(new[]{songs[0]},0,"","%title%"," ");string old=songs[0].Source;var renameAction=FileTagAction.Apply(rename,Path.Combine(root,"undo"));Check(File.Exists(rename[0].Target)&&!File.Exists(old),"Tag → Dateiname ausgeführt");renameAction.Restore(false);songs[0].Source=old;
  var rename2=TagConversion.Plan(new[]{songs[0]},2,"%artist% - %title%","%title% - %artist%","");Check(rename2[0].Target.EndsWith("Title 0 - Artist 0.mp3"),"Dateiname → Dateiname Vorschau");var r2=FileTagAction.Apply(rename2,Path.Combine(root,"undo"));r2.Restore(false);songs[0].Source=old;
  var textPlan=TagConversion.Plan(new[]{songs[0]},3,"%artist%;%title%","","",new[]{"Édith Piaf;La vie en rose"});var tx=FileTagAction.Apply(textPlan,Path.Combine(root,"undo"));Check(TagFields.Read(old)["artist"]=="Édith Piaf","Textdatei → Tag UTF-8");tx.Restore(false);songs[0]=MediaMetadata.Read(old);
  var transfer=TagConversion.Plan(new[]{songs[0]},4,"","$upper(%artist%)","composer");var tr=FileTagAction.Apply(transfer,Path.Combine(root,"undo"));Check(TagFields.Read(old)["composer"]=="ARTIST 0","Tag → Tag ausgeführt");tr.Restore(false);
  Bad(()=>TagConversion.Plan(songs,0,"","gleich",""),"Namenskollision vor Schreiben abgewiesen");Bad(()=>TagConversion.Plan(songs,3,"%title%","","",new[]{"a"}),"Fehlende Textzeilen abgewiesen");
  foreach(string format in new[]{"MP3","FLAC","WAV","M4A","OGG","OPUS"}){var o=new AudioOptions{Format=format,SampleRate=44100,Channels=1};string output=AudioAdvanced.FfmpegBatch(new[]{songs[0]},root,"/usr/bin/ffmpeg",o,()=>{},(n,t,s)=>{});Check(Directory.GetFiles(output,"*."+format.ToLowerInvariant()).Length==1,"FFmpeg konvertiert "+format);}
  foreach(string mode in new[]{"Schneiden","Zusammenfügen","Audio extrahieren"}){var o=new AudioOptions{Format="WAV",Mode=mode,Start=mode=="Schneiden"?.2:0,End=mode=="Schneiden"?1:0,Filter="Lautheit -16 LUFS"};string output=AudioAdvanced.FfmpegBatch(songs.Take(2).ToArray(),root,"/usr/bin/ffmpeg",o,()=>{},(n,t,s)=>{});Check(Directory.GetFiles(output,"*.wav").Length==(mode=="Zusammenfügen"?1:2),"FFmpeg "+mode);}
  Console.WriteLine("BESTANDEN: "+count+" Prüfungen mit echten MP3-Dateien");
 }
}
